            currentUser={state.currentUser}
          />

          {/* Commercial Work View Modal - COMMERCIAL ONLY */}
          <CommercialWorkView 
            isOpen={showCommercialWorkView}
            onClose={() => setShowCommercialWorkView(false)}
            currentUser={state.currentUser}
          />
        </>
      )}
    </div>
  );
};

export default App;

