    const categories = new Set(programaFilteredProducts.map(p => p.category || 'OTROS'));

    // Orden de categorías según el catálogo
    const categoryOrder = {
      'ALTOS': 1,
      'ALTOS GOLA': 2,
      'BAJOS': 3,
      'BAJOS GOLA': 4,
      'SEMICOLUMNAS': 5,
      'SEMICOLUMNAS GOLA': 6,
