    const series = new Set(filteredProducts.map(p => p.series || 'GENERAL'));
    return Array.from(series).sort();
  }, [allProducts, state.currentModule, catalogs, selectedPrograma, selectedCategory]);

  const sortedItems = useMemo(() => {
