  }, []);

  // Función helper para detectar tipo de mueble especial
  const getSpecialType = useCallback((code, name) => {
    const c = code?.toUpperCase() || '';
    const n = name?.toUpperCase() || '';

    // Por código primero
    if (c.includes('AM') || c.includes('BM')) return 'MICRO';
